34	    @Mapping(target = "registrationDate", expression = "java(ownerDto.getRegistrationDate() != null ? ownerDto.getRegistrationDate() : java.time.LocalDate.now())")
35	    Owner toOwner(OwnerFieldsDto ownerDto);
36	
